-- H2 projections for home overview, cross-type search and the AI assistant queue.
CREATE TABLE IF NOT EXISTS opportunities(id BIGINT PRIMARY KEY,campus_id BIGINT,notice_id BIGINT,title VARCHAR(256),category VARCHAR(32),organizer VARCHAR(128),summary VARCHAR(100000),deadline TIMESTAMP,status VARCHAR(32) DEFAULT 'published',source_type VARCHAR(16) DEFAULT 'manual',source_name VARCHAR(128),external_id VARCHAR(128),official_reference VARCHAR(512),is_stale BOOLEAN DEFAULT FALSE,rules_version INT DEFAULT 0,version INT DEFAULT 0,created_by BIGINT,updated_by BIGINT,created_at TIMESTAMP,updated_at TIMESTAMP,deleted_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS reminders(id BIGINT PRIMARY KEY,user_id BIGINT,target_type VARCHAR(32),target_id BIGINT,remind_at TIMESTAMP,status VARCHAR(32) DEFAULT 'pending',created_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS privacy_settings(user_id BIGINT PRIMARY KEY,personalization_enabled BOOLEAN DEFAULT FALSE,history_enabled BOOLEAN DEFAULT FALSE,nearby_enabled BOOLEAN DEFAULT FALSE,version INT DEFAULT 0,created_at TIMESTAMP,updated_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS conversations(id BIGINT PRIMARY KEY,campus_id BIGINT,type VARCHAR(32),title VARCHAR(128),context_type VARCHAR(32),context_id BIGINT,created_by BIGINT,version INT DEFAULT 0,created_at TIMESTAMP,updated_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS conversation_members(id BIGINT PRIMARY KEY,conversation_id BIGINT,user_id BIGINT,unread_count INT DEFAULT 0,last_read_message_id BIGINT,last_read_at TIMESTAMP,created_at TIMESTAMP,UNIQUE(conversation_id,user_id));
CREATE TABLE IF NOT EXISTS notifications(id BIGINT PRIMARY KEY,campus_id BIGINT,user_id BIGINT,type VARCHAR(32),title VARCHAR(128),content VARCHAR(512),target_type VARCHAR(32),target_id BIGINT,read_at TIMESTAMP,dedup_key VARCHAR(64) UNIQUE,created_at TIMESTAMP);
